sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float count;
uniform float width;
uniform float angle;
layout(color) uniform half4 color;
uniform float alpha;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float2 d = coord - center * size;
    float t = (atan(d.y, d.x) - radians(angle)) / 6.2831853 * floor(count + 0.5);
    float e = abs(fract(t) - 0.5);
    float px = max(length(d), 1.0) * 6.2831853 / floor(count + 0.5);
    float s = width > 0.0 ? clamp((width * 0.5 - e) * px + 0.5, 0.0, 1.0) : 0.0;
    float3 base = float3(src.rgb) / float(src.a);
    float3 rgb = mix(base, float3(color.rgb), s * float(color.a) * clamp(alpha, 0.0, 1.0));
    return half4(half3(rgb) * src.a, src.a);
}
